const leadsState={query:'',type:'all',purchase:'all',origin:'all',period:'all',tag:'all',visible:'list'};
const leadRecords=()=>clientsState.items.filter(c=>!c.archived);
const leadPaid=c=>(c.receivables||[]).filter(x=>x.status==='pago');
const leadAmount=c=>leadPaid(c).reduce((n,x)=>n+(Number(x.amount)||0),0);
const leadDate=c=>String(c.createdAt||c.start||'').slice(0,10);
const leadType=c=>pipelineStageOf(c)==='Fechado'?'Cliente':'Lead';
function leadFiltered(){const q=leadsState.query.toLocaleLowerCase('pt-BR');return leadRecords().filter(c=>[c.name,c.email,c.phone,c.company,...(c.tags||[])].some(x=>String(x||'').toLocaleLowerCase('pt-BR').includes(q))&&(leadsState.type==='all'||leadType(c)===leadsState.type)&&(leadsState.purchase==='all'||(leadsState.purchase==='yes')===!!leadPaid(c).length)&&(leadsState.origin==='all'||(c.origin||'Cadastro manual')===leadsState.origin)&&(leadsState.tag==='all'||(c.tags||[]).includes(leadsState.tag))&&(leadsState.period==='all'||(leadDate(c)&&Date.now()-new Date(leadDate(c)+'T12:00:00').getTime()<=Number(leadsState.period)*864e5)))}
function leadNavigate(page){menu.querySelector(`[data-page="${page}"]`)?.click()}
function leadFunnel(id){if(!clientsState.items.some(c=>c.id===id))return;pipelineState.focusId=id;pipelineState.view='kanban';pipelineState.hidden.clear();pipelineState.collapsed.clear();leadNavigate('Pipelines')}
function leadHistoryEvents(c){const events=[];const add=(date,text,kind='Registro')=>{if(date)events.push({date:String(date),text,kind})};add(c.createdAt||c.start,'Entrada na base de contatos','Entrada');if(c.start&&c.createdAt&&c.start!==c.createdAt)add(c.start,'Início do atendimento','Cliente');(c.receivables||[]).forEach(x=>add(x.paidAt||x.date||x.due,`${x.status==='pago'?'Pagamento registrado':'Conta a receber'}: ${money(x.amount)}${x.description?' · '+x.description:''}`,'Financeiro'));(dashState.activities||[]).filter(x=>x.clientId===c.id).forEach(x=>add(x.timestamp||x.date,x.text,'Ação'));(dashState.meetings||[]).filter(x=>x.clientId===c.id).forEach(x=>add(x.date,`${x.cancelled?'Reunião cancelada':'Reunião agendada'}: ${x.title} às ${x.time||'—'}${x.responsible?' · '+x.responsible:''}`,'Reunião'));(dashState.tasks||[]).filter(x=>x.clientId===c.id).forEach(x=>add(x.createdAt||x.due,`Tarefa ${x.done?'concluída':'registrada'}: ${x.title}`,'Tarefa'));return events.sort((a,b)=>b.date.localeCompare(a.date))}
function renderLeadHistory(id){const c=clientsState.items.find(x=>x.id===id);if(!c){renderLeads();return}leadsState.visible='history';const w=document.querySelector('.workspace');w.className='workspace leads-mode';document.querySelector('#page-title').textContent='Leads';const paid=leadPaid(c),events=leadHistoryEvents(c);w.innerHTML=`<div class="leads-shell"><header class="lead-detail-head"><button class="lead-back" data-leads="back" aria-label="Voltar para Leads">←</button><div><h2>${esc(c.name)} <span class="lead-badge">${leadType(c)}</span></h2><p>Na base desde ${formatDate(leadDate(c))} · ${esc(c.email||'Sem e-mail')} · ${esc(c.phone||'Sem telefone')}</p></div><button class="lead-button" data-leads="funnel" data-id="${esc(c.id)}">↗ Abrir no funil</button></header><div class="lead-stats"><div><small>Compras pagas</small><strong>${paid.length}</strong></div><div><small>Total pago</small><strong>${money(leadAmount(c))}</strong></div><div><small>Ticket médio pago</small><strong>${money(paid.length?leadAmount(c)/paid.length:0)}</strong></div><div><small>Etapa atual</small><strong>${esc(pipelineStageOf(c))}</strong></div></div><section class="lead-panel"><h3>Jornada</h3><div class="lead-journey"><div><span>✓</span><b>Entrou na base</b><small>${formatDate(leadDate(c))}</small></div><div><span>◷</span><b>${esc(pipelineStageOf(c))}</b><small>Etapa atual do funil</small></div>${paid.length?`<div><span>✓</span><b>Primeiro pagamento</b><small>${formatDate(paid[0].paidAt||paid[0].date||paid[0].due)}</small></div>`:''}</div></section><section class="lead-panel"><h3>Histórico detalhado</h3>${events.length?`<ol class="lead-timeline">${events.map(x=>`<li><span class="lead-event-type">${esc(x.kind)}</span><strong>${esc(x.text)}</strong><small>${esc(x.date.length===10?formatDate(x.date):x.date)}</small></li>`).join('')}</ol>`:'<p class="lead-empty">Ainda não há ações registradas para este contato.</p>'}</section></div>`}
function renderLeads(){leadsState.visible='list';const w=document.querySelector('.workspace');w.className='workspace leads-mode';document.querySelector('#page-title').textContent='Leads';const all=leadRecords(),rows=leadFiltered(),origins=[...new Set(all.map(c=>c.origin||'Cadastro manual'))],tags=[...new Set(all.flatMap(c=>c.tags||[]))];w.innerHTML=`<div class="leads-shell"><header class="leads-head"><div><h2>Leads</h2><p>Todos os contatos da base, com filtros e histórico de cada um.</p></div><button class="lead-button" data-leads="export">⇩ Exportar CSV</button></header><div class="lead-stats"><div><small>Contatos</small><strong>${all.length}</strong></div><div><small>Clientes</small><strong>${all.filter(c=>leadType(c)==='Cliente').length}</strong></div><div><small>Já compraram</small><strong>${all.filter(c=>leadPaid(c).length).length}</strong></div><div><small>Receita recebida</small><strong class="lead-green">${money(all.reduce((n,c)=>n+leadAmount(c),0))}</strong></div></div><div class="lead-filters"><label class="lead-search">⌕ <input id="leads-query" placeholder="Nome, e-mail, telefone ou empresa..." value="${esc(leadsState.query)}" aria-label="Buscar contatos"></label><select data-lead-filter="type" aria-label="Tipo"><option value="all">Todos</option><option value="Lead" ${leadsState.type==='Lead'?'selected':''}>Leads</option><option value="Cliente" ${leadsState.type==='Cliente'?'selected':''}>Clientes</option></select><select data-lead-filter="purchase" aria-label="Comprou ou não"><option value="all">Comprou ou não</option><option value="yes" ${leadsState.purchase==='yes'?'selected':''}>Já comprou</option><option value="no" ${leadsState.purchase==='no'?'selected':''}>Não comprou</option></select><select data-lead-filter="origin" aria-label="Origem"><option value="all">Toda origem</option>${origins.map(x=>`<option ${leadsState.origin===x?'selected':''} value="${esc(x)}">${esc(x)}</option>`).join('')}</select><select data-lead-filter="period" aria-label="Data de entrada"><option value="all">Qualquer data</option><option value="7" ${leadsState.period==='7'?'selected':''}>7 dias</option><option value="30" ${leadsState.period==='30'?'selected':''}>30 dias</option><option value="90" ${leadsState.period==='90'?'selected':''}>90 dias</option></select><select data-lead-filter="tag" aria-label="Tags"><option value="all">◇ Tags</option>${tags.map(x=>`<option ${leadsState.tag===x?'selected':''} value="${esc(x)}">${esc(x)}</option>`).join('')}</select></div><div class="lead-table-wrap"><table class="lead-table"><thead><tr><th>CONTATO</th><th>TAGS</th><th>ORIGEM</th><th>ENTROU</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody>${rows.map(c=>`<tr><td><button class="lead-name" data-leads="history" data-id="${esc(c.id)}">${esc(c.name)}</button> <span class="lead-badge">${leadType(c)}</span><small>${esc(c.company||c.name)} · ${esc(c.email||'Sem e-mail')}${c.phone?' · '+esc(c.phone):''}</small></td><td>${(c.tags||[]).length?(c.tags||[]).map(t=>`<span class="lead-tag">${esc(t)}</span>`).join(' '):'<span class="lead-muted">—</span>'}</td><td>${esc(c.origin||'Cadastro manual')}</td><td>${formatDate(leadDate(c))}</td><td class="lead-row-actions"><button data-leads="history" data-id="${esc(c.id)}" title="Histórico de ${esc(c.name)}" aria-label="Histórico de ${esc(c.name)}">♧</button><button data-leads="funnel" data-id="${esc(c.id)}" title="Abrir ${esc(c.name)} no funil" aria-label="Abrir ${esc(c.name)} no funil">↗</button></td></tr>`).join('')||'<tr><td colspan="5" class="lead-empty">Nenhum contato encontrado com estes filtros.</td></tr>'}</tbody></table></div><p class="lead-count">${rows.length} ${rows.length===1?'contato':'contatos'} exibidos</p></div>`}
function exportLeads(){const rows=leadFiltered(),columns=['Nome','Tipo','Empresa','E-mail','Telefone','Tags','Origem','Entrada','Etapa','Compras pagas','Total pago'];const safe=x=>{let s=String(x??'');if(/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const csv='\uFEFF'+[columns,...rows.map(c=>[c.name,leadType(c),c.company,c.email,c.phone,(c.tags||[]).join(', '),c.origin||'Cadastro manual',formatDate(leadDate(c)),pipelineStageOf(c),leadPaid(c).length,leadAmount(c)])].map(r=>r.map(safe).join(';')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='leads.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-leads]');if(!b)return;const a=b.dataset.leads;if(a==='history')renderLeadHistory(b.dataset.id);else if(a==='funnel')leadFunnel(b.dataset.id);else if(a==='back')renderLeads();else if(a==='export')exportLeads()});
document.addEventListener('input',e=>{if(e.target.id==='leads-query'){leadsState.query=e.target.value;const pos=e.target.selectionStart;renderLeads();const input=document.querySelector('#leads-query');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.dataset.leadFilter){leadsState[e.target.dataset.leadFilter]=e.target.value;renderLeads()}});
